from pathlib import Path
import html,json
ROOT=Path(__file__).resolve().parent.parent/'dist'
ORIGIN='https://sukha-travel-20261103.racinglight1.chatgpt.site'
def esc(s): return html.escape(str(s),quote=True)
def link(url,text,cls='button'): return f'<a class="{cls}" href="{url}">{text}<span aria-hidden="true">↗</span></a>'
nav=[('/destinations/','Destinations'),('/private-china-tours/','Private Journeys'),('/signature-experiences/','Signature Experiences'),('/silk-road-luxury-trains/','Luxury Rail'),('/yangtze-river-cruises/','Yangtze Cruises'),('/our-story/','Our Story')]
def header(path):return '<header><a class="brand" href="/" aria-label="SUKHA home"><span class="logo-crop"><img src="/assets/logo.jpg" alt="行界 SUKHA"></span><span class="brand-note">PRIVATE CHINA JOURNEYS</span></a><nav id="navigation">'+''.join(f'<a href="{u}" '+('aria-current="page"' if path.startswith(u) else '')+f'>{n}</a>' for u,n in nav)+'</nav>'+link('/plan-my-trip/','Plan My Trip','button nav-cta')+'<button id="menu-toggle" aria-label="Open navigation" aria-expanded="false" aria-controls="navigation">☰</button></header>'
def footer():return '''<footer><div class="footer-top"><div><a class="wordmark" href="/">SUKHA<span>行界 · CHINA, BEYOND THE EXPECTED.</span></a><p>Private journeys. Remarkable experiences.<br>A deeper China.</p></div><div><h3>Explore China</h3><a href="/private-china-tours/">Private journeys</a><a href="/silk-road-luxury-trains/">Luxury rail</a><a href="/yangtze-river-cruises/">Yangtze cruises</a></div><div><h3>Get to know us</h3><a href="/our-story/">Our story</a><a href="/travel-journal/">The China Journal</a><a href="/booking-information/">How booking works</a></div><div><h3>Start a conversation</h3><a href="/plan-my-trip/">Plan my trip ↗</a><a href="/privacy/">Privacy & this preview</a><p>Contact channels to be confirmed.</p></div></div><div class="footer-bottom"><span>© 2026 SUKHA · 行界</span><span>Private design preview · Inquiries are not yet sent.</span></div></footer>'''
def cta():return '<section class="final-cta"><p class="eyebrow">A JOURNEY THAT IS YOURS</p><h2>Your China story<br>starts here.</h2><p>Tell us what inspires you. Let’s shape the journey around you.</p>'+link('/plan-my-trip/','Start Planning','button light')+'</section>'
def write(path,title,desc,body):
 p=ROOT/path.strip('/')/'index.html' if path!='/' else ROOT/'index.html';p.parent.mkdir(parents=True,exist_ok=True)
 p.write_text(f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)} | SUKHA</title><meta name="description" content="{esc(desc)}"><link rel="canonical" href="{ORIGIN}{path}"><meta property="og:title" content="{esc(title)}"><meta property="og:description" content="{esc(desc)}"><meta property="og:type" content="website"><meta property="og:url" content="{ORIGIN}{path}"><meta property="og:image" content="{ORIGIN}/assets/great-wall.jpg"><link rel="stylesheet" href="/style.css"><script src="/app.js" defer></script></head><body><a class="skip" href="#main">Skip to content</a>'+header(path)+'<main id="main">'+body+'</main>'+footer()+'</body></html>')
def intro(kicker,title,copy):return f'<section class="page-intro wrap"><p class="eyebrow">{kicker}</p><h1>{title}</h1><p class="lede">{copy}</p></section>'
def head(kicker,title,copy=''):return f'<div class="section-head"><div><p class="eyebrow">{kicker}</p><h2>{title}</h2></div><p>{copy}</p></div>'
themes=[('01','The Silk Road','Ancient civilizations, luxury rail & legendary journeys','/signature-experiences/silk-road/','silk','DUNHUANG · KASHGAR · THE PAMIRS'),('02','The Yangtze River','Remarkable river journeys through the heart of China','/yangtze-river-cruises/','river','CHONGQING · THREE GORGES · YICHANG'),('03','The Wild Plateau','In search of snow leopards & high-altitude wildlife','/wildlife/sanjiangyuan-snow-leopard/','wild','QINGHAI · SANJIANGYUAN'),('04','Living China','Pandas, living traditions & cities of tomorrow','/signature-experiences/living-china/','living','CHENGDU · CHONGQING')]
def theme_cards():return '<div class="theme-grid">'+''.join(f'<a class="theme-card {cl}" href="{u}"><div class="theme-art" aria-hidden="true"><span>{n}</span><i></i></div><p class="eyebrow">{region}</p><h3>{name}</h3><p>{desc}</p><span class="text-link">Discover this world ↗</span></a>' for n,name,desc,u,cl,region in themes)+'</div>'
