write('/private-china-tours/','Private China Tours','Explore ten suggested private China itineraries, from first-time journeys to culture, family and nature-led travel.',private)
for slug,title,days,cat,places,desc,cl in trips:
 overview='<div class="route-overview" aria-label="Suggested route">'+''.join(f'<span><b>{i:02d}</b>{p}</span>'+('<i>→</i>' if i<len(places) else '') for i,p in enumerate(places,1))+'</div>'
 itinerary=''
 for day in range(1,days+1):
  p=places[min((day-1)*len(places)//days,len(places)-1)]
  text=(f'Arrive in {p}. Leave time to settle in and discuss the pace of the days ahead.' if day==1 else 'Bring the journey to a close, with onward travel arranged around your confirmed plans.' if day==days else f'Discover {p} through a balance of local stories, landmark visits and time of your own. Activities and transfers will be refined with your travel designer.')
  itinerary+=f'<details><summary><span>DAY {day:02d}</span> {p}<b>＋</b></summary><p>{text}</p></details>'
 body=intro('PRIVATE JOURNEY · SUGGESTED ITINERARY',title,desc)+f'<section class="wrap compact"><div class="trip-tags"><span>{days} days suggested</span><span>{cat}</span><span>Private & customizable</span></div></section><section class="wrap section content-columns"><div><p class="eyebrow">WHY THIS JOURNEY</p><h2>A starting point.<br>Your own story.</h2><p>{desc} Choose the experiences that matter to you, and adapt the pace, stays and route together.</p><h3>Meaningful encounters</h3><ul><li>Time to explore the character of each place beyond its best-known sights.</li><li>Space for food, culture and everyday discoveries that reflect your interests.</li><li>A route planned as a whole, with rest and travel time considered together.</li></ul></div><aside><p class="eyebrow">MAKE IT YOURS</p><h3>Begin with what you love.</h3><p>This is a planning concept. Dates, access, transport and accommodation are not yet confirmed.</p>'+link('/plan-my-trip/?type=private&journey='+slug,'Customize This Journey')+'</aside></section><section class="ivory"><div class="wrap section">'+head('THE JOURNEY AT A GLANCE','Your route through China.')+overview+'<p class="quiet">Schematic route, not a geographic map. Transfer times will be supplied with your personalized proposal.</p></div></section><section class="wrap section narrow">'+head('ROOM FOR YOUR OWN DISCOVERIES','Day by day.')+itinerary+'</section><section class="wrap section"><div class="info-grid">'+''.join(f'<article><h3>{h}</h3><p>{p}</p></article>' for h,p in [('Accommodation & style','Choose your preferred hotel style and comfort level in the inquiry. Specific properties, room types and availability require confirmation.'),('Inclusions & exclusions','Your final quotation should identify accommodation, transport, guiding, admissions and meals, together with exclusions and optional costs. No services are included or priced in this preview.'),('Season & activity level','Share your dates, mobility needs and preferred pace. Seasonal conditions, walking requirements and any access restrictions must be reviewed for the final route.'),('Practical arrangements','Dietary requests, guide language, private vehicles and onward travel should be confirmed in writing. Verify current entry requirements with official sources before booking.')])+'</div></section>'+cta()
 write('/journeys/'+slug+'/',title,desc,body)
rail=intro('SILK ROAD LUXURY RAIL JOURNEYS','Travel through history.<br><em>Stay with the journey.</em>','A rail-led journey across ancient cultures, thoughtfully connected with private experiences before and after your time on board.')+'<section class="wrap feature compact"><div class="feature-art silk"><div class="rail-lines"></div><div class="art-caption"><small>ROUTE CONCEPT · NOT A CONFIRMED DEPARTURE</small><strong>The Silk Road,<br>reimagined.</strong><span>Chengdu / Xining · Western China</span></div></div><div class="feature-copy"><p class="eyebrow">THE COLLECTION TAKES SHAPE</p><h2>More than<br>a way to travel.</h2><p>Explore a journey that brings together time on board, Silk Road heritage and private extensions tailored to your curiosity.</p><div class="notice">The train collection is being prepared. Operators, routes, cabin details and departures will appear here once verified. No live availability is displayed.</div>'+link('/plan-my-trip/?type=rail','Request Rail Availability')+'<br>'+link('/plan-my-trip/?type=rail&intent=custom','Customize My Rail Journey','text-link')+'</div></section><section class="ivory"><div class="wrap section">'+head('THE EXPERIENCE, CONSIDERED','What will shape your rail journey?')+'<div class="info-grid">'+''.join(f'<article><span class="eyebrow">0{i}</span><h3>{t}</h3><p>{d}</p></article>' for i,(t,d) in enumerate([('The train experience','Compare the confirmed operator, route and onboard spaces once the collection is available.'),('Cabins & suites','Review real photography, layouts, room sizes and facilities before choosing a cabin.'),('Life on board','Understand the dining arrangements, service languages and onboard activities for your departure.'),('Off-train discoveries','Discuss cultural visits and private extensions in places such as Dunhuang and Kashgar.')],1))+'</div></div></section><section class="wrap section"><div class="section-head"><div><p class="eyebrow">BEFORE YOU CHOOSE</p><h2>Every detail deserves<br>a clear answer.</h2></div></div><div class="table-scroll"><table><thead><tr><th>What to confirm</th><th>What your proposal should explain</th></tr></thead><tbody>'+''.join(f'<tr><th>{a}</th><td>{b}</td></tr>' for a,b in [('Departure & route','Actual departure city, dates, stops and the final operating itinerary.'),('Cabin & capacity','Confirmed cabin category, occupancy, facilities and available allocation.'),('Included services','Meals, excursions, transfers and any optional or additional charges.'),('Before travel','Luggage limits, accessibility, age conditions and any route-specific requirements.'),('Changes & cancellation','The operator’s applicable payment, change and cancellation conditions.')])+'</tbody></table></div></section><section class="wrap section">'+head('EXTEND THE STORY','Beyond the railway.')+'<div class="journal-grid"><a href="/signature-experiences/silk-road/"><span>CULTURE & EXCHANGE</span><h3>The Silk Road</h3><p>Follow the stories behind an extraordinary cultural landscape.</p><b>Explore ↗</b></a><a href="/signature-experiences/xuanzang/"><span>FAITH & DISCOVERY</span><h3>In the Footsteps of Xuanzang</h3><p>A cultural journey concept inspired by curiosity, knowledge and exchange.</p><b>Explore ↗</b></a><a href="/journeys/ancient-silk-road/"><span>PRIVATE EXTENSIONS</span><h3>Make time for more.</h3><p>Explore a suggested private itinerary across western China.</p><b>Explore ↗</b></a></div></section>'+cta()
