experiences=[
('/signature-experiences/silk-road/','THE SILK ROAD','Ancient stories.<br>New perspectives.','Explore the Silk Road through its cultural landscapes, artistic traditions and stories of exchange.','silk',[('Art & belief','Make space for the cultural heritage of Dunhuang and the stories behind the places you visit.'),('Oasis cultures','Discover the idea of a journey connecting Turpan, Kuqa and Kashgar.'),('Travel your way','Combine a private journey with a rail segment only when its route and operating details are confirmed.')],'/journeys/ancient-silk-road/','Explore a suggested itinerary'),
('/signature-experiences/xuanzang/','IN THE FOOTSTEPS OF XUANZANG','A journey of faith,<br>knowledge & discovery.','An editorial journey concept inspired by Xuanzang and the exchange of ideas along the Silk Road.','silk',[('A cultural lens','Explore the relationship between travel, learning and Buddhist heritage.'),('A journey, not a reconstruction','The final itinerary will be designed around accessible sites; this is not a claim to reproduce an exact historical route.'),('Thoughtful interpretation','Specialist interpretation and access need to be confirmed for your dates.')],'/plan-my-trip/?type=private&interest=Silk%20Road','Shape this journey'),
('/wildlife/sanjiangyuan-snow-leopard/','THE WILD PLATEAU','Wild places.<br>A quieter kind of wonder.','A specialist journey concept centered on high-altitude landscapes and respectful wildlife observation.','wild',[('Observation, with patience','Wild animals move freely. Snow leopard sightings can never be promised.'),('Access comes first','A trip can only be proposed after local access, permissions, qualified partners and operating conditions are verified.'),('Considered preparation','Altitude, remoteness, mobility and personal suitability require careful planning. Seek individual medical advice where needed.')],'/plan-my-trip/?type=private&interest=Nature%20%26%20Wildlife','Explore the possibility'),
('/signature-experiences/living-china/','LIVING CHINA','Meet China,<br>in its everyday moments.','Pandas, tea, food, craft and cities of tomorrow. Discover the stories in between the landmarks.','living',[('Chengdu, slowly','Build time around tea culture, Sichuan flavors and local neighborhoods.'),('A city in layers','Look at Chongqing through its rivers, stairways and changing perspectives.'),('Living traditions','Meet craft and food through respectful experiences, subject to host availability.')],'/journeys/chengdu-chongqing-yangtze/','Explore the connected journey'),
('/experiences/chengdu-pandas/','CHENGDU PANDA EXPERIENCES','A little closer<br>to a remarkable world.','Combine a considered panda visit with the flavors, tea culture and everyday life of Chengdu.','living',[('Choose your visit carefully','The facility, entry arrangements and daily plan must be confirmed before booking.'),('Respectful observation','Keep to visitor rules. Animal contact, handling or volunteer access is not promised.'),('Make a day of Chengdu','Leave time for local food and a slower look at the city beyond the panda experience.')],'/journeys/chengdu-local-life/','Explore Chengdu'),
('/experiences/chongqing-night-tour/','CHONGQING CITY EXPERIENCES','China’s extraordinary<br>vertical city.','Discover a city shaped by changing levels, riverside perspectives and the energy of everyday life.','living',[('Follow the layers','A walking route can explore stairways and neighborhoods at a pace suited to you.'),('Stay for the evening','Build an evening around city views and food, with weather and opening conditions considered.'),('Connect to the river','Combine time in Chongqing with a verified Yangtze sailing and onward private travel.')],'/journeys/chengdu-chongqing-yangtze/','Connect city & river')]
for path,k,title,desc,cl,items,url,button in experiences:
 body=intro(k,title,desc)+'<section class="wrap section compact"><div class="experience-banner '+cl+'"><span>'+k+'</span><p>Curiosity is a good place to begin.</p></div><div class="info-grid three">'+''.join(f'<article><h3>{t}</h3><p>{d}</p></article>' for t,d in items)+'</div><p class="quiet">Experience concept · Final access, partners and arrangements require confirmation.</p>'+link(url,button)+'</section>'+cta()
 write(path,k.title(),desc,body)
destinations=[('beijing','Beijing','Imperial stories & city life','classic-china'),('shanghai','Shanghai','Historic streets & contemporary perspectives','classic-china'),('xian','Xi’an','Ancient capitals & cultural discovery','classic-china'),('guilin','Guilin','River landscapes & a gentler pace','guilin-family'),('zhangjiajie','Zhangjiajie','Landscape-led exploration','nature-china'),('yunnan','Yunnan','Old towns & unhurried discoveries','yunnan-slow-journey'),('xinjiang','Xinjiang','Oasis cultures & Silk Road stories','xinjiang-explorer'),('chengdu','Chengdu','Pandas, tea & Sichuan flavors','chengdu-local-life'),('chongqing','Chongqing','A city of rivers & changing levels','chengdu-chongqing-yangtze'),('tibet','Tibet','Plateau landscapes & cultural journeys',None),('inner-mongolia','Inner Mongolia','Open horizons & grassland stories',None)]
write('/destinations/','China Destinations','Explore China-wide journey ideas, including Beijing, Shanghai, Xi’an, Xinjiang, Chengdu, Chongqing, Tibet and Inner Mongolia.',intro('ONE COUNTRY. ENDLESS DISCOVERIES.','Where will curiosity<br><em>take you?</em>','Start with somewhere you have always imagined. Or discover a place you hadn’t thought to look.')+'<section class="wrap section compact"><div class="destination-grid">'+''.join(f'<article id="{slug}"><span class="eyebrow">CHINA / {i:02d}</span><h2>{name}</h2><p>{desc}</p>'+link('/journeys/'+journey+'/' if journey else '/plan-my-trip/?destination='+slug,'Explore a journey' if journey else 'Plan a journey','text-link')+('<p class="quiet">Access and route feasibility need individual confirmation.</p>' if slug=='tibet' else '')+'</article>' for i,(slug,name,desc,journey) in enumerate(destinations,1))+'</div></section>'+cta())
write('/our-story/','Our Story','The SUKHA approach to thoughtfully designed private China travel.',intro('SUKHA · 行界','A deeper connection.<br><em>A journey of your own.</em>','We believe the most meaningful journeys make room for both the places you dream of and the discoveries you never expected.')+'<section class="wrap section content-columns"><div><p class="eyebrow">OUR DIRECTION</p><h2>China-wide.<br>Personally considered.</h2><p>SUKHA is building a boutique China travel experience around private journeys, with distinctive perspectives on the Silk Road, the Yangtze River, high-altitude nature and the living cultures of Chengdu and Chongqing.</p><p>Our approach begins with curiosity: what draws you to China, how you like to travel, and the moments you hope to bring home.</p></div><aside><p class="eyebrow">THE WAY WE THINK</p><h3>Travel closer.<br>Tread thoughtfully.</h3><p>Respect local communities, follow site and wildlife rules, and choose experiences with their context in mind.</p></aside></section><section class="ivory"><div class="wrap section">'+head('A PERSONAL PROCESS','From an idea<br>to a considered journey.')+steps()+'</div></section><section class="wrap section narrow"><p class="eyebrow">PEOPLE & CREDENTIALS</p><h2>Real stories.<br>Real people.</h2><p>Verified company information, our travel designers and authorized guest stories will be introduced here before the website begins accepting live inquiries. This preview does not display invented testimonials, awards or team profiles.</p>'+link('/booking-information/','What to confirm before booking','text-link')+'</section>'+cta())
write('/booking-information/','How Planning & Booking Work','Understand the proposed planning process and the information to confirm before a SUKHA journey.',intro('CLARITY, FROM THE START','A thoughtful journey<br>begins with clear details.','Understand the process, then make each decision with the information you need.')+'<section class="wrap section compact">'+steps()+'</section><section class="wrap section narrow"><h2>Before any booking or payment.</h2>'+''.join(f'<details><summary>{t}<b>＋</b></summary><p>{d}</p></details>' for t,d in [('Your contracting company','The full legal company name, travel business credentials, address and responsible service provider must be supplied before booking. These details are pending owner confirmation.'),('Your proposal & quotation','The confirmed route, dates, hotels, transport, guide language, meals and activities should be documented, along with exclusions and optional charges.'),('Payment & currency','A formal proposal must specify the payee, currency, approved payment channel, deposit and balance schedule. This preview accepts no payments.'),('Changes, cancellation & refunds','Terms must match the confirmed products and operators, including train and cruise conditions. No cancellation or refund policy is implied by this preview.'),('Travel support','Confirm how to contact your travel designer before departure and the actual support arrangements during your trip. No response-time or around-the-clock service promise is made here.')])+'</section>'+cta())
write('/privacy/','Privacy & This Preview','How the SUKHA website prototype handles planning-form information.',intro('PRIVACY & PREVIEW INFORMATION','Your plans stay<br>in this page.','The planning form is a local demonstration. It does not submit your information to SUKHA or send an email.')+'<section class="wrap section narrow"><h2>How the preview works</h2><p>Entries remain in the current page while you use the form. They are not stored by the form in cookies or browser storage. You can generate a summary and choose to copy it to your clipboard. Reloading or leaving the page clears the entries.</p><h3>Optional contact fields</h3><p>Use sample details while reviewing the prototype. No travel designer will receive these entries, and no booking or inquiry is created.</p><h3>Site delivery</h3><p>The hosting platform may process ordinary access information to deliver the website. The interface does not add marketing analytics or tracking pixels. A complete business privacy notice, data controller details and retention policy are required before live inquiries are enabled.</p><h3>Photography & product information</h3><p>The homepage Great Wall photograph is illustrative destination photography from Unsplash. Abstract route illustrations are editorial artwork, not photographs of trains, cabins, ships or wildlife experiences.</p></section>')
def field(label,name,kind='text',extra=''):
 return f'<label>{label}<input type="{kind}" name="{name}" {extra}></label>'
def select(label,name,options):return f'<label>{label}<select name="{name}">'+''.join(f'<option>{esc(x)}</option>' for x in options)+'</select></label>'
form=intro('LET’S BEGIN WITH YOU','Tell us what<br><em>inspires you.</em>','A few thoughtful details are all it takes to begin shaping a journey.')+'''<section class="wrap section compact planning-layout"><aside class="planning-aside"><p class="eyebrow">YOUR NEXT CHAPTER</p><h2>A conversation.<br>Not a commitment.</h2><p>Choose your journey type and share a little about the way you want to travel.</p><ol><li>Share your ideas</li><li>Review your preferences</li><li>Prepare your inquiry</li></ol><div class="notice">Preview mode: this form creates a summary only. Nothing is sent, and no inquiry or booking is made.</div><a class="text-link" href="/privacy/">Privacy & this preview ↗</a></aside><div><div class="inquiry-types" role="group" aria-label="Inquiry type"><button type="button" data-type="private" aria-pressed="true" class="active">Private Journey</button><button type="button" data-type="rail" aria-pressed="false">Luxury Rail</button><button type="button" data-type="cruise" aria-pressed="false">Yangtze Cruise</button></div><form id="planning-form"><div class="step-indicator"><span id="step-label">STEP 1 OF 2 · YOUR IDEAS</span><i><b id="step-progress"></b></i></div><fieldset id="step-one"><legend id="form-heading">What does your China look like?</legend><div id="private-fields" class="type-fields"><label>What inspires you?<select name="interest"><option>Classic China & Private Touring</option><option>Silk Road & Ancient Cultures</option><option>Nature & Wildlife</option><option>Pandas & Local Culture</option><option>Family Journeys</option><option>Not sure yet</option></select></label>'''+field('Destinations or a journey you liked','destination','text','placeholder="A place, a route, or a blank page" maxlength="150"')+'''</div><div id="rail-fields" class="type-fields" hidden>'''+select('Preferred departure area','railRoute',['Flexible / advise me','Chengdu — subject to confirmed routes','Xining — subject to confirmed routes','Other — tell us below'])+field('Cabin preference','railCabin','text','placeholder="Your preferred style or cabin category" maxlength="150"')+select('Private extensions','railExtension',['I would like advice','Before the rail journey','After the rail journey','Before and after','Rail journey only'])+'''</div><div id="cruise-fields" class="type-fields" hidden>'''+select('Travel direction','cruiseDirection',['Either direction','Chongqing → Yichang','Yichang → Chongqing'])+select('Preferred cruise style','cruiseStyle',['Any style','Essential','Premium','Luxury'])+select('Preferred cruise duration','cruiseDuration',['Flexible','3 nights','4 nights'])+field('Cabin preference','cruiseCabin','text','placeholder="Cabin category, deck, or advise me" maxlength="150"')+select('Transfers & private extensions','cruiseExtension',['Please advise me','Transfers only','Private travel before / after','Cruise only'])+'''</div><div class="form-grid">'''+field('Preferred date (optional)','date','date')+select('Date flexibility','flexibility',['My dates are flexible','Within a few days','Fixed dates'])+field('Adults','adults','number','value="2" min="1" max="50" required')+field('Children','children','number','value="0" min="0" max="20" required')+field('Total journey length (days)','days','number','value="14" min="1" max="90" required')+field('Children’s ages (if applicable)','ages','text','maxlength="100" placeholder="For example: 8 and 12"')+'''</div><button type="button" class="button" id="next-step">Continue to Preferences <span>→</span></button></fieldset><fieldset id="step-two" hidden><legend>A little more about your travel style.</legend><div class="form-grid">'''+select('Budget per person, excluding international flights','budget',['Please advise me','Under US$3,000','US$3,000–5,000','US$5,000–8,000','US$8,000+'])+select('Hotel preference','hotel',['Please advise me','Comfortable & well located','Boutique & characterful','Luxury hotels','A thoughtful mix'])+select('Travel pace','pace',['Balanced','Relaxed','Active'])+field('Your name (optional in preview)','name','text','maxlength="100" autocomplete="name"')+field('Email (optional in preview)','email','email','maxlength="150" autocomplete="email" placeholder="Use sample details for this preview"')+field('Country / region','country','text','maxlength="100" autocomplete="country-name"')+field('WhatsApp (optional)','whatsapp','tel','maxlength="60" autocomplete="tel" placeholder="Include country code"')+'''</div><label>Anything else you would like us to know?<textarea name="notes" rows="4" maxlength="2000" placeholder="Interests, travel style, food preferences or questions. Avoid sensitive personal details in this preview."></textarea></label><label class="check"><input type="checkbox" name="privacy" required><span>I understand this is a local preview and my inquiry will not be sent. <a href="/privacy/">Read the preview privacy information.</a></span></label><div class="form-actions"><button type="button" class="back-button" id="previous-step">← Back</button><button class="button" type="submit">Prepare My Inquiry <span>↗</span></button></div></fieldset></form><div id="inquiry-result" hidden tabindex="-1"><p class="eyebrow">YOUR IDEAS, BROUGHT TOGETHER</p><h2>Your journey begins<br>with this idea.</h2><p class="notice">Summary prepared — not sent. This preview has not created an inquiry or a booking.</p><pre id="inquiry-summary"></pre><div class="form-actions"><button class="button" id="copy-inquiry">Copy Summary</button><button class="back-button" id="edit-inquiry">Edit My Plans</button></div><p id="copy-status" class="quiet" aria-live="polite"></p></div></div></section>'''
write('/plan-my-trip/','Plan My Trip','Prepare a private journey, luxury rail or Yangtze cruise inquiry with SUKHA. Two-step planning form prototype.',form)
articles=[('first-time-china','Your first China journey, thoughtfully planned','PLANNING',[('Begin with your interests','Think about the moments you want from China: cultural landmarks, local food, contemporary cities, nature or shared time with family. Let those interests guide the route.'),('Give the journey room to breathe','A shorter list of places can leave more time to experience each one. Consider travel between destinations as part of the itinerary, rather than treating every day as a sightseeing day.'),('Choose a starting point','A Beijing, Xi’an and Shanghai concept offers one way to begin. A route through Chengdu, Chongqing and the Yangtze creates a different balance. Both should be adjusted to your dates and pace.'),('Confirm the practical details','Before booking, review access requirements, accommodation, transfers, service language and the exact terms of the proposal. Entry rules should always be checked against current official guidance.')]),('rail-or-river','Rail or river? Find your rhythm','PERSPECTIVES',[('Let the journey be part of the story','Rail and river journeys offer different ways of moving through a place. Choose according to the landscapes and experiences that draw you in, then examine the actual product.'),('Think about time on board','Review the real cabin, public spaces, meals, service languages and schedule. Editorial imagery is no substitute for a confirmed operator’s product details.'),('Consider the experiences ashore','Ask which visits are included and how much flexibility you will have. Private extensions can create room for interests beyond the core itinerary.'),('Compare the full journey','Look at transfers, additional nights, optional expenses and cancellation terms alongside the headline journey. The complete plan matters more than an isolated product.')]),('two-weeks-in-china','Two weeks. A China that feels like you.','ITINERARIES',[('Choose a theme, not a checklist','Fourteen days can support many different journeys. A first encounter with China, a culture-focused Silk Road trip or a city-and-river combination will each use that time differently.'),('Balance icons with quieter days','Place a slower morning after an active day, and leave room for the experiences that cannot be rushed. Your preferred rhythm should shape the route.'),('Connect places thoughtfully','Transport availability and transfer times need to be checked for your dates. Avoid assuming that every destination can be added without changing the pace.'),('Use an itinerary as an invitation','Start with a suggested route, then adapt the stops, stays and activities. The final plan should feel personal rather than exhaustive.')])]
write('/travel-journal/','The China Journal','Thoughtful starting points for planning a private journey through China.',intro('NOTES FOR THE CURIOUS','The China Journal.','Ideas for looking closer, choosing your rhythm and making a journey your own.')+'<section class="wrap section compact"><div class="journal-grid">'+''.join(f'<a href="/travel-journal/{s}/"><span>{k}</span><h3>{t}</h3><p>{parts[0][1]}</p><b>Read the story ↗</b></a>' for s,t,k,parts in articles)+'</div></section>'+cta())
for slug,title,kind,parts in articles:
 write('/travel-journal/'+slug+'/',title,'Planning perspectives from SUKHA: '+title,intro('THE CHINA JOURNAL · '+kind,title,'A thoughtful starting point for your own journey.')+'<article class="wrap section narrow compact">'+''.join(f'<section class="article-section"><h2>{h}</h2><p>{p}</p></section>' for h,p in parts)+link('/private-china-tours/','Find a journey to make your own','text-link')+'</article>'+cta())
# A private preview should not be indexed before business details are finalized.
(ROOT/'robots.txt').write_text('User-agent: *\nDisallow: /\n')
paths=sorted('/'+str(p.parent.relative_to(ROOT)).strip('.')+'/' for p in ROOT.rglob('index.html'))
(ROOT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+ORIGIN+p.replace('//','/')+'</loc></url>' for p in paths)+'</urlset>')
print('Generated',len(paths),'English pages')
